-- M5 market jobs (plan §6 `market-server`, `market-byok`): the state of each built-in source, and the two instance-wide
-- scans the worker needs. The table is generated by drizzle-kit from src/schema.ts; the rest is hand-written.
CREATE TABLE "market_provider_state" (
	"provider" "market_provider" PRIMARY KEY NOT NULL,
	"status" varchar(16) NOT NULL,
	"paused_until" timestamp with time zone,
	"quota_used" integer DEFAULT 0 NOT NULL,
	"quota_limit" integer,
	"quota_reset_at" timestamp with time zone,
	"updated_at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "market_provider_state_status_check" CHECK (status in ('untested', 'connected', 'unverified', 'invalid_key', 'quota_exhausted', 'rate_limited', 'error', 'unconfigured')),
	CONSTRAINT "market_provider_state_quota_check" CHECK ("market_provider_state"."quota_used" >= 0)
);
--> statement-breakpoint
-- Global like market_quotes (no user data): written by the worker, read by the app for "API kurs & pasar".
ALTER TABLE market_provider_state ENABLE ROW LEVEL SECURITY;
--> statement-breakpoint
ALTER TABLE market_provider_state FORCE ROW LEVEL SECURITY;
--> statement-breakpoint
CREATE POLICY market_provider_state_worker ON market_provider_state FOR ALL TO wf_worker USING (true) WITH CHECK (true);
--> statement-breakpoint
CREATE POLICY market_provider_state_read ON market_provider_state FOR SELECT TO wf_app USING (true);
--> statement-breakpoint
GRANT SELECT, INSERT, UPDATE ON market_provider_state TO wf_worker;
--> statement-breakpoint
GRANT SELECT ON market_provider_state TO wf_app;
--> statement-breakpoint
-- "Tes koneksi" and "Sinkronkan harga" run in the app with the user's own key (the result is shown at once), so the
-- app stores those results too; the owner policy keeps them the user's own rows.
GRANT INSERT, UPDATE ON user_quotes TO wf_app;
--> statement-breakpoint
-- The scans below run once for every user, so they cannot set `app.user_id`: SECURITY DEFINER functions (owner
-- wf_migrate, which these read policies let through) that return symbols, currencies, ids, and time zones only.
CREATE POLICY assets_market_targets ON assets FOR SELECT TO wf_migrate USING (true);
--> statement-breakpoint
CREATE POLICY market_credentials_byok_users ON market_credentials FOR SELECT TO wf_migrate USING (true);
--> statement-breakpoint
-- The union of every user's symbols the built-in sources price (CoinMarketCap: one call for all, research §2.0.1):
-- crypto assets that are fetched (not priced by hand), and gold spot (XAU, also the base of Antam estimates).
CREATE FUNCTION wf_market_server_targets() RETURNS TABLE (market market, symbol text, quote_currency char(3))
  LANGUAGE sql STABLE SECURITY DEFINER SET search_path = pg_catalog, public
AS $$
  SELECT 'crypto'::public.market, coalesce(meta -> 'symbols' ->> 'coinmarketcap', symbol), quote_currency
    FROM public.assets WHERE market = 'crypto' AND price_mode IN ('server', 'byok')
  UNION
  SELECT 'gold_spot'::public.market, coalesce(meta -> 'symbols' ->> 'fawazahmed0', symbol), quote_currency
    FROM public.assets WHERE market = 'gold_spot' AND price_mode IN ('server', 'byok')
  UNION
  SELECT 'gold_spot'::public.market, 'XAU', quote_currency FROM public.assets WHERE market = 'gold_antam'
  ORDER BY 1, 2, 3
$$;
--> statement-breakpoint
REVOKE ALL ON FUNCTION wf_market_server_targets() FROM PUBLIC;
--> statement-breakpoint
GRANT EXECUTE ON FUNCTION wf_market_server_targets() TO wf_worker;
--> statement-breakpoint
-- Users with an active BYOK key (`market-byok` jobs, `mkb.{userId}.{slot}`), with their time zone.
CREATE FUNCTION wf_market_byok_users() RETURNS TABLE (user_id uuid, time_zone text)
  LANGUAGE sql STABLE SECURITY DEFINER SET search_path = pg_catalog, public
AS $$
  SELECT DISTINCT u.id, u.timezone FROM public.market_credentials c JOIN public.users u ON u.id = c.user_id
  WHERE c.active AND u.two_factor_enabled AND u.deletion_requested_at IS NULL
  ORDER BY u.id
$$;
--> statement-breakpoint
REVOKE ALL ON FUNCTION wf_market_byok_users() FROM PUBLIC;
--> statement-breakpoint
GRANT EXECUTE ON FUNCTION wf_market_byok_users() TO wf_worker;
--> statement-breakpoint
-- FR-ST4: physical retention, including per-user logs, without giving the worker broad DELETE access.
CREATE POLICY market_api_logs_retention ON market_api_logs FOR DELETE TO wf_migrate USING (true);
--> statement-breakpoint
CREATE FUNCTION wf_market_purge_logs(p_now timestamptz) RETURNS bigint
  LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path = pg_catalog, public
AS $$
DECLARE deleted bigint;
BEGIN
  DELETE FROM public.market_api_logs WHERE at < least(p_now, now()) - interval '30 days';
  GET DIAGNOSTICS deleted = ROW_COUNT;
  RETURN deleted;
END
$$;
--> statement-breakpoint
REVOKE ALL ON FUNCTION wf_market_purge_logs(timestamptz) FROM PUBLIC;
--> statement-breakpoint
GRANT EXECUTE ON FUNCTION wf_market_purge_logs(timestamptz) TO wf_worker;
--> statement-breakpoint
CREATE POLICY market_api_logs_retention_read ON market_api_logs FOR SELECT TO wf_migrate USING (true);
